1 | /**
2 |  * Typed client for the AutorIA REST API (docs/api_contract.yaml).
3 |  * All response shapes mirror the contract via lib/types.ts — never invent fields here.
4 |  */
5 | import type {
6 |   AuthorSummary,
7 |   DocumentUploadAccepted,
8 |   GenerateRequest,
9 |   GenerateResponse,
10 |   StyleProfile,
11 | } from "@/lib/types";
12 | 
13 | /**
14 |  * Thrown when a style-profile request returns HTTP 404.
15 |  * Per contract: 404 means "author unknown OR StyleProfile not yet computed"
16 |  * — this is an EMPTY state, not a server error. Callers must distinguish it
17 |  * from NetworkError / 5xx (which are error states with retry).
18 |  */
19 | export class NotFoundError extends Error {
20 |   readonly status = 404 as const;
21 |   constructor(label: string) {
22 |     super(`${label} returned 404 (not found or not yet computed)`);
23 |     this.name = "NotFoundError";
24 |   }
25 | }
26 | 
27 | const API_BASE = process.env.NEXT_PUBLIC_API_URL ?? "http://localhost:8000";
28 | 
29 | async function parseOrThrow<T>(res: Response, label: string): Promise<T> {
30 |   if (!res.ok) {
31 |     throw new Error(`${label} failed with status ${res.status}`);
32 |   }
33 |   return res.json() as Promise<T>;
34 | }
35 | 
36 | /** GET /api/authors — preloaded authors plus any added via document upload. */
37 | export async function listAuthors(): Promise<AuthorSummary[]> {
38 |   const res = await fetch(`${API_BASE}/api/authors`, { cache: "no-store" });
39 |   return parseOrThrow<AuthorSummary[]>(res, "GET /api/authors");
40 | }
41 | 
42 | /**
43 |  * POST /api/authors/{author_id}/documents — multipart .txt/.md upload (202 async).
44 |  *
45 |  * CONTRACT GAP: the API has no create-author endpoint, yet listAuthors is
46 |  * documented as returning authors "added via document upload". The add-author
47 |  * flow therefore posts to a fresh slug and expects the backend to auto-create
48 |  * it; the contract's 404 for unknown author_id contradicts this. Flagged for
49 |  * the Sprint 1 contract pairing session.
50 |  */
51 | export async function uploadAuthorDocument(
52 |   authorId: string,
53 |   file: File,
54 |   title?: string,
55 | ): Promise<DocumentUploadAccepted> {
56 |   const form = new FormData();
57 |   form.append("file", file);
58 |   if (title) form.append("title", title);
59 |   const res = await fetch(
60 |     `${API_BASE}/api/authors/${encodeURIComponent(authorId)}/documents`,
61 |     { method: "POST", body: form },
62 |   );
63 |   return parseOrThrow<DocumentUploadAccepted>(
64 |     res,
65 |     "POST /api/authors/{id}/documents",
66 |   );
67 | }
68 | 
69 | /**
70 |  * GET /api/authors/{author_id}/style-profile — Style DNA fingerprint v1.0.
71 |  *
72 |  * Throws NotFoundError for HTTP 404 (author unknown or profile not yet computed).
73 |  * Throws a plain Error for any other non-ok status (5xx, network failure, etc.).
74 |  */
75 | export async function getStyleProfile(authorId: string): Promise<StyleProfile> {
76 |   const res = await fetch(
77 |     `${API_BASE}/api/authors/${encodeURIComponent(authorId)}/style-profile`,
78 |     { cache: "no-store" },
79 |   );
80 |   if (res.status === 404) {
81 |     throw new NotFoundError(`GET /api/authors/${authorId}/style-profile`);
82 |   }
83 |   return parseOrThrow<StyleProfile>(
84 |     res,
85 |     `GET /api/authors/${authorId}/style-profile`,
86 |   );
87 | }
88 | 
89 | /** Derives a URL-safe author slug from a display name (client-side id proposal). */
90 | export function slugifyAuthorName(name: string): string {
91 |   return name
92 |     .normalize("NFD")
93 |     .replace(/[\u0300-\u036f]/g, "")
94 |     .toLowerCase()
95 |     .replace(/[^a-z0-9]+/g, "-")
96 |     .replace(/^-+|-+$/g, "");
97 | }
98 | 
99 | /**
100 |  * POST /api/generate — run vanilla + AutorIA generation in parallel on the backend.
101 |  *
102 |  * Uses AbortController with a 10 s timeout so a hanging Watsonx call resolves
103 |  * to a timeout state rather than an infinite spinner (design-system §1 / §7.4).
104 |  *
105 |  * Return contract:
106 |  *   200       → resolves with GenerateResponse
107 |  *   AbortError → throws with name "AbortError" (timeout path)
108 |  *   other      → throws a plain Error (error path)
109 |  */
110 | export async function generateText(
111 |   authorId: string,
112 |   prompt: string,
113 | ): Promise<GenerateResponse> {
114 |   const controller = new AbortController();
115 |   const timerId = setTimeout(() => controller.abort(), 10_000);
116 | 
117 |   try {
118 |     const body: GenerateRequest = { author_id: authorId, prompt };
119 |     const res = await fetch(`${API_BASE}/api/generate`, {
120 |       method: "POST",
121 |       headers: { "Content-Type": "application/json" },
122 |       body: JSON.stringify(body),
123 |       signal: controller.signal,
124 |     });
125 |     return parseOrThrow<GenerateResponse>(res, "POST /api/generate");
126 |   } finally {
127 |     clearTimeout(timerId);
128 |   }
129 | }
