export default function VerifyPage() {
  const [inputMode, setInputMode] = useState<"paste" | "upload">("paste");
  const [token, setToken] = useState("");
  const [fileName, setFileName] = useState<string | null>(null);
  const [state, setState] = useState<PageState>({ kind: "idle" });
  const fileInputRef = useRef<HTMLInputElement>(null);

  /** Extract a JWS token string from a .jws/.json file's text. */
  async function readFileToken(file: File): Promise<string> {
    const text = await file.text();
    const trimmed = text.trim();
    // Try to parse as JSON with a jws_token field; fall back to bare token.
    try {
      const parsed: unknown = JSON.parse(trimmed);
      if (
        parsed !== null &&
        typeof parsed === "object" &&
        "jws_token" in parsed &&
        typeof (parsed as { jws_token: unknown }).jws_token === "string"
      ) {
        return (parsed as { jws_token: string }).jws_token;
      }
    } catch {
      // Not JSON — treat the whole content as a bare token.
    }
    return trimmed;
  }

  function handleFileChange(e: React.ChangeEvent<HTMLInputElement>) {
    const file = e.target.files?.[0];
    if (!file) return;
    setFileName(file.name);
    readFileToken(file)
      .then((t) => setToken(t))
      .catch(() => setToken(""));
  }

  function handleClear() {
    setToken("");
    setFileName(null);
    setState({ kind: "idle" });
    if (fileInputRef.current) fileInputRef.current.value = "";
  }

  async function handleSubmit(e: React.FormEvent) {
    e.preventDefault();
    const jwsToken = token.trim();
    if (!jwsToken) return;

    setState({ kind: "submitting" });
    const response = await verifyPassport(jwsToken);

    if (response.valid && response.payload !== null) {
      setState({
        kind: "valid",
        response: response as VerifyResponse & {
          valid: true;
          payload: PassportPayload;
        },
      });
    } else if (
      !response.valid &&
      response.errors.some((e) => e.code === "jwks_unavailable") &&
      response.errors.length === 1 &&
      response.errors[0].message.startsWith("Network error:")
    ) {
      // Synthesised network error from the client wrapper
      setState({ kind: "network_error" });
    } else {
      setState({ kind: "invalid", errors: response.errors });
    }
  }

  const isSubmitting = state.kind === "submitting";

  return (
    <div className="flex flex-col gap-8 max-w-3xl">
      <div>
        <h1 className="font-heading text-3xl font-semibold tracking-tight">
          {t.pageTitle}
        </h1>
        <p className="mt-2 text-muted-foreground">{t.pageSubtitle}</p>
      </div>

      {/* Input card */}
      <Card>
        <CardHeader>
          {/* Mode tabs */}
          <div className="flex gap-1 self-start rounded-lg border border-border bg-muted/50 p-0.5">
            <button
              type="button"
              onClick={() => {
                setInputMode("paste");
                handleClear();
              }}
              className={`rounded-md px-3 py-1 text-sm font-medium transition-colors ${
                inputMode === "paste"
                  ? "bg-background text-foreground shadow-sm"
                  : "text-muted-foreground hover:text-foreground"
              }`}
            >
              {t.tabPaste}
            </button>
            <button
              type="button"
              onClick={() => {
                setInputMode("upload");
                handleClear();
              }}
              className={`rounded-md px-3 py-1 text-sm font-medium transition-colors ${
                inputMode === "upload"
                  ? "bg-background text-foreground shadow-sm"
                  : "text-muted-foreground hover:text-foreground"
              }`}
            >
              {t.tabUpload}
            </button>
          </div>
        </CardHeader>

        <CardContent>
          <form onSubmit={(e) => void handleSubmit(e)} className="flex flex-col gap-4">
            {inputMode === "paste" ? (
              <div className="flex flex-col gap-1.5">
                <label
                  htmlFor="jws-token"
                  className="text-sm font-medium"
                >
                  {t.tokenLabel}
                </label>
                <textarea
                  id="jws-token"
                  value={token}
                  onChange={(e) => setToken(e.target.value)}
                  placeholder={t.tokenPlaceholder}
                  rows={4}
                  spellCheck={false}
                  className="w-full resize-none rounded-lg border border-border bg-background px-3 py-2 font-mono text-xs leading-relaxed text-foreground placeholder:text-muted-foreground focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring disabled:opacity-50"
                  disabled={isSubmitting}
                />
              </div>
            ) : (
              <div className="flex flex-col gap-1.5">
                <span className="text-sm font-medium">{t.fileLabel}</span>
                <div className="flex items-center gap-3">
                  <Button
                    type="button"
                    variant="outline"
                    size="sm"
                    onClick={() => fileInputRef.current?.click()}
                    disabled={isSubmitting}
                  >
                    {t.fileButton}
                  </Button>
                  <span className="text-sm text-muted-foreground">
                    {fileName ?? t.fileEmpty}
                  </span>
                </div>
                <input
                  ref={fileInputRef}
                  type="file"
                  accept=".jws,.json"
                  className="sr-only"
                  onChange={handleFileChange}
                />
              </div>
            )}

            <div className="flex gap-2">
              <Button
                type="submit"
                disabled={isSubmitting || !token.trim()}
              >
                {isSubmitting ? t.verifyingButton : t.verifyButton}
              </Button>
              {token && (
                <Button
                  type="button"
                  variant="ghost"
                  onClick={handleClear}
                  disabled={isSubmitting}
                >
                  {t.clearButton}
                </Button>
              )}
            </div>
          </form>
        </CardContent>
      </Card>

      {/* Result area */}
      {state.kind === "idle" && (
        <div className="flex flex-col items-center gap-2 py-12 text-center text-muted-foreground">
          <p className="text-base font-medium">{t.idleHeading}</p>
          <p className="text-sm">{t.idleBody}</p>
        </div>
      )}

      {state.kind === "submitting" && (
        <div className="flex items-center justify-center py-12">
          <span className="text-sm text-muted-foreground animate-pulse">
            {t.verifyingButton}
          </span>
        </div>
      )}

      {state.kind === "valid" && (
        <div className="flex flex-col gap-4">
          {/* Green verdict banner */}
          <div className="rounded-xl border border-fit-high/40 bg-fit-high/10 px-4 py-3">
            <p className="font-heading text-lg font-semibold text-fit-high">
              {t.verifiedTitle}
            </p>
            <p className="text-sm text-muted-foreground">{t.verifiedSubtitle}</p>
          </div>

          {/* Decoded payload */}
          <Card>
            <CardContent className="pt-4">
              <PayloadTable payload={state.response.payload} />
            </CardContent>
          </Card>
        </div>
      )}

      {state.kind === "invalid" && (
        <div className="flex flex-col gap-4">
          {/* Red verdict banner */}
          <div className="rounded-xl border border-destructive/40 bg-destructive/10 px-4 py-3">
            <p className="font-heading text-lg font-semibold text-destructive">
              {t.invalidTitle}
            </p>
          </div>

          {/* Error list */}
          <Card>
            <CardContent className="pt-4">
              <ul className="flex flex-col gap-2">
                {state.errors.map((err, i) => (
                  <li
                    key={i}
                    className="flex items-start gap-2 rounded-lg border border-border bg-muted/30 px-3 py-2 text-sm"
                  >
                    <code className="shrink-0 font-mono text-xs text-muted-foreground mt-0.5">
                      {err.code}
                    </code>
                    <span>{errorMessage(err)}</span>
                  </li>
                ))}
              </ul>
            </CardContent>
          </Card>
        </div>
      )}

      {state.kind === "network_error" && (
        <div className="flex flex-col gap-4">
          {/* Network error banner */}
          <div className="rounded-xl border border-amber-500/40 bg-amber-500/10 px-4 py-3">
            <p className="font-heading text-lg font-semibold text-amber-600 dark:text-amber-400">
              {t.networkErrorTitle}
            </p>
            <p className="text-sm text-muted-foreground">{t.networkErrorBody}</p>
          </div>
          <div>
            <Button
              type="button"
              variant="outline"
              onClick={() => setState({ kind: "idle" })}
            >
              {t.retryButton}
            </Button>
          </div>
        </div>
      )}
    </div>
  );
}

